pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address attacker, uint value, bytes calldata data) public {
        // Assume caller is not owner to trigger mutant difference
        vm.assume(attacker != c.owner());
        // Bound value to avoid overflow
        value = bound(value, 0, address(c).balance);
        // Record balances before
        uint ownerBefore = c.owner().balance;
        uint contractBefore = address(c).balance;
        // Call sendMoney as attacker (will only succeed in mutant where non-owner can call)
        (bool ok, ) = address(c).call{value: 0}(abi.encodeWithSelector(c.sendMoney.selector, c.owner(), value, data));
        // Record balances after
        uint ownerAfter = c.owner().balance;
        uint contractAfter = address(c).balance;
        // General rule: contract+owner balance is invariant unless send succeeded
        // If call reverted, balances unchanged; if succeeded, value moves from contract to owner
        if (!ok) {
            assertTrue(ownerBefore == ownerAfter && contractBefore == contractAfter);
        } else {
            assertTrue(ownerAfter == ownerBefore + value && contractAfter == contractBefore - value);
        }
    }
}

