pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _target, uint256 _value, bytes memory _data) public {
        // Bound _value to avoid overflow and excessive gas (max 1e5 wei)
        _value = bound(_value, 0, 100000);
        vm.deal(address(c), 1 ether);
        uint256 balanceBefore = address(c).balance;

        // Call sendMoney (onlyOwner, so we must be owner; owner = msg.sender in constructor)
        // The owner is the test contract (this) because setUp() deploys C from this address
        c.sendMoney(_target, _value, _data);

        uint256 balanceAfter = address(c).balance;
        // General rule: balance decreases by exactly _value (if sendMoney succeeds) or stays same (if fails)
        // We know sendMoney always succeeds because it reverts on failure, so balance must decrease by _value.
        assertTrue(balanceAfter == balanceBefore - _value, "balance after sendMoney should be balanceBefore - _value");
    }
}

