pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public { 
        c = new C(); 
        owner = payable(address(this)); // The test contract is the owner via msg.sender in constructor
        // But in the test, the contract's owner is address(this) because new C() is called from this contract
        // So we set owner to address(this) to match the contract's perspective
        // Actually, new C() sets owner = msg.sender; who is the test contract (address(this))
        owner = address(this);
    }

    function testFuzz_property(address _target, uint256 _value, bytes memory _data) public {
        // Bound _value to avoid overflow and gas limits: max 1e6 wei
        vm.assume(_value <= 1_000_000);
        // Ensure _target is not the contract itself to avoid recursion
        vm.assume(_target != address(c));
        // Also ensure _target is a valid address (not zero)
        vm.assume(_target != address(0));

        // Give the contract some initial balance (e.g., via fallback)
        // We send some ether to c via the owner to have a balance
        // But we need to call the fallback so that depositsCount increments
        // Since we are the owner, we can call fallback by sending ether directly
        // vm.deal(address(c), 1 ether); // This sets balance without calling fallback
        // Instead, we call c as owner (msg.sender = address(this))
        // Actually, we can just send value to c via a raw call
        (bool success, ) = address(c).call{value: 2_000_000}('');
        require(success, "Initial funding failed");

        // Now call sendMoney to send _value to _target
        c.sendMoney(_target, _value, _data);

        // Now, we measure the owner's balance before withdraw
        uint256 ownerBalBefore = address(msg.sender).balance;

        // Call withdraw(_value) – this is what the bug affects
        c.withdraw(_value);

        uint256 ownerBalAfter = address(msg.sender).balance;
        uint256 actualWithdrawn = ownerBalAfter - ownerBalBefore;

        // The general rule: the actual withdrawn amount must equal the supplied _value
        // In the correct contract, it should, but in the buggy version it withdraws the whole balance
        assertTrue(actualWithdrawn == _value, "withdraw should send exactly _value");
    }
}

