pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address _target, uint256 _value, bytes memory _data) public {
        // Bound inputs to avoid overflow and ensure reasonable values
        _value = bound(_value, 1, 1e18);
        vm.assume(_target != address(0) && _target != address(c));

        // Fund the contract with enough ETH
        vm.deal(address(c), _value);

        // Call sendMoney as owner
        vm.prank(c.owner());
        (bool success, ) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", _target, _value, _data));
        vm.assume(success);  // only consider successful sendMoney calls

        // Now try to withdraw exactly _value - should succeed in reference but revert in buggy version (since bug sends entire balance)
        uint256 balanceBefore = address(c).balance;
        vm.prank(c.owner());
        (bool withdrawSuccess, ) = address(c).call(abi.encodeWithSignature("withdraw(uint256)", _value));
        // In reference C, withdraw(_value) should succeed and reduce balance by exactly _value
        // In buggy M, withdraw transfers address(this).balance (which is balanceBefore), so after call, balance is 0
        uint256 balanceAfter = address(c).balance;

        // General rule: after sendMoney(_target, _value, _data) succeeded,
        // calling withdraw(_value) must result in balance decreasing by exactly _value
        // (i.e., balanceBefore - balanceAfter == _value)
        assertTrue(withdrawSuccess && (balanceBefore - balanceAfter == _value), "Withdraw did not send exact _value");
    }
}

